import { BOARD_LAYOUT } from './boardLayout.js';
import type { Card, CellIndex } from './types.js';

export const BOARD_SIZE = 10;
export const CELL_COUNT = 100;
/** The four free corner cells. */
export const CORNERS: readonly CellIndex[] = [0, 9, 90, 99];

/** length 100, null at corners. Generated by scripts/generate-board.ts. */
export const BOARD: readonly (Card | null)[] = BOARD_LAYOUT;

export const isCorner = (cell: CellIndex): boolean =>
  cell === 0 || cell === 9 || cell === 90 || cell === 99;

export const isValidCell = (cell: unknown): cell is CellIndex =>
  typeof cell === 'number' && Number.isInteger(cell) && cell >= 0 && cell < CELL_COUNT;

export const rowOf = (cell: CellIndex): number => Math.floor(cell / BOARD_SIZE);
export const colOf = (cell: CellIndex): number => cell % BOARD_SIZE;

const CELLS_BY_CARD = new Map<Card, CellIndex[]>();
BOARD.forEach((card, idx) => {
  if (card === null) return;
  const list = CELLS_BY_CARD.get(card) ?? [];
  list.push(idx);
  CELLS_BY_CARD.set(card, list);
});

/** The board cells showing `card` (empty for jacks). */
export function cellsFor(card: Card): CellIndex[] {
  return [...(CELLS_BY_CARD.get(card) ?? [])];
}
